using System.Reflection;using System.Runtime.CompilerServices;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Effects;using DeskCanvas.Core;
namespace DeskCanvas.App.Windows;
internal static class V30RuntimePolish{[ModuleInitializer]internal static void Init(){EventManager.RegisterClassHandler(typeof(Border),FrameworkElement.LoadedEvent,new RoutedEventHandler(Loaded));EventManager.RegisterClassHandler(typeof(MainWindow),FrameworkElement.LoadedEvent,new RoutedEventHandler(MainLoaded));EventManager.RegisterClassHandler(typeof(MediaWindow),FrameworkElement.LoadedEvent,new RoutedEventHandler(MediaLoaded));EventManager.RegisterClassHandler(typeof(BuiltInContentPicker),FrameworkElement.LoadedEvent,new RoutedEventHandler(PickerLoaded));}private static void Loaded(object s,RoutedEventArgs e){if(s is not Border b)return;if(b.Effect is DropShadowEffect&&IsStandardCard(b))b.Effect=null;if(IsSystem(b))FitSystem(b);}private static bool IsStandardCard(Border b)=>b.Child is System.Windows.Controls.Panel p&&p.Descendants().OfType<TextBlock>().Any(t=>t.Text is "SYSTEM STATUS" or "再生中"||t.FontSize>=45);private static bool IsSystem(Border b)=>b.Child is System.Windows.Controls.Panel p&&p.Descendants().OfType<TextBlock>().Any(t=>t.Text=="SYSTEM STATUS");private static void FitSystem(Border b){b.SizeChanged+=(_,__)=>{if(b.Child is not UIElement c)return;var scale=SystemStatusResponsiveMath.Scale(b.ActualWidth,b.ActualHeight);c.RenderTransformOrigin=new Point(.5,0);c.RenderTransform=new ScaleTransform(scale.X,scale.Y);};}private static void MainLoaded(object s,RoutedEventArgs e){if(s is MainWindow w){w.AddLayerButtons();w.AddClockTextEditor();}}private static void MediaLoaded(object s,RoutedEventArgs e){if(s is MediaWindow w){w.ApplyTextClock();w.SizeChanged+=(_,__)=>w.ApplyTextClock();}}private static void PickerLoaded(object s,RoutedEventArgs e){if(s is BuiltInContentPicker p)p.AddTextClockOptions();}}
internal static class SystemStatusResponsiveMath{internal static (double X,double Y) Scale(double width,double height){var x=Math.Clamp(width/300d,.55,1.45);var y=Math.Clamp(height/210d,.55,1.45);return(x,y);}}
internal static class VisualTreeExt{internal static IEnumerable<DependencyObject> Descendants(this DependencyObject root){for(var i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var c=VisualTreeHelper.GetChild(root,i);yield return c;foreach(var d in c.Descendants())yield return d;}}}
partial class MediaWindow{internal void ApplyTextClock(){if(item.ContentKind!=CanvasContentKinds.Clock||!item.Clock.Backgroundless||content.View is not Border card)return;card.Effect=null;card.Background=Brushes.Transparent;card.BorderThickness=new Thickness(0);card.Padding=new Thickness(0);card.CornerRadius=new CornerRadius(0);foreach(var text in card.Descendants().OfType<TextBlock>()){text.Foreground=ClockTextStyle.Foreground(item.Clock.TextColor,text.Foreground);text.FontFamily=ClockTextStyle.Family(item.Clock.FontFamily);text.FontWeight=ClockTextStyle.Weight(item.Clock.FontWeight);}ItemContent.RenderTransformOrigin=new Point(.5,.5);ItemContent.LayoutTransform=new ScaleTransform(Math.Clamp(item.Width/300d,.32,4),Math.Clamp(item.Height/150d,.32,4));}}
internal static class ClockTextStyle{internal static FontFamily Family(string value){try{return string.IsNullOrWhiteSpace(value)?SystemFonts.MessageFontFamily:new FontFamily(value);}catch{return SystemFonts.MessageFontFamily;}}internal static Brush Foreground(string value,Brush fallback){try{return string.IsNullOrWhiteSpace(value)?fallback:new SolidColorBrush((Color)ColorConverter.ConvertFromString(value));}catch{return fallback;}}internal static FontWeight Weight(ClockFontWeight v)=>v switch{ClockFontWeight.Light=>FontWeights.Light,ClockFontWeight.SemiBold=>FontWeights.SemiBold,ClockFontWeight.Bold=>FontWeights.Bold,ClockFontWeight.Black=>FontWeights.Black,_=>FontWeights.Regular};}
partial class MainWindow{private CheckBox? textClockCheck;private TextBox? textClockFont,textClockColor;private ComboBox? textClockWeight;internal void AddLayerButtons(){if(EditorPanel.Children.OfType<WrapPanel>().Any(p=>Equals(p.Tag,"v30-layer")))return;var panel=new WrapPanel{Tag="v30-layer",Margin=new Thickness(0,10,0,0)};foreach(var pair in new[]{("最前面",2),("上へ",1),("下へ",-1),("最背面",-2)}){var button=new Button{Content=pair.Item1,ToolTip=pair.Item1};button.Click+=(_,__)=>MoveLayer(pair.Item2);panel.Children.Add(button);}EditorPanel.Children.Add(panel);}internal void AddClockTextEditor(){if(textClockCheck is not null)return;textClockCheck=new CheckBox{Content="背景なし・文字だけ",Margin=new Thickness(0,12,0,3)};textClockFont=new TextBox{ToolTip="フォント名",Margin=new Thickness(0,2,0,2)};textClockColor=new TextBox{ToolTip="文字色 (#RRGGBB)",Margin=new Thickness(0,2,0,2)};textClockWeight=new ComboBox{ItemsSource=Enum.GetValues<ClockFontWeight>(),Margin=new Thickness(0,2,0,4)};foreach(var c in new Control[]{textClockCheck,textClockFont,textClockColor,textClockWeight}){if(c is CheckBox q){q.Checked+=ClockChanged;q.Unchecked+=ClockChanged;}else if(c is TextBox t)t.LostFocus+=ClockChanged;else if(c is ComboBox z)z.SelectionChanged+=ClockChanged;}EditorPanel.Children.Add(new TextBlock{Text="文字時計",Margin=new Thickness(0,12,0,3)});EditorPanel.Children.Add(textClockCheck);EditorPanel.Children.Add(new TextBlock{Text="フォント"});EditorPanel.Children.Add(textClockFont);EditorPanel.Children.Add(new TextBlock{Text="文字色"});EditorPanel.Children.Add(textClockColor);EditorPanel.Children.Add(new TextBlock{Text="太さ"});EditorPanel.Children.Add(textClockWeight);ItemsList.SelectionChanged+=(_,__)=>RefreshTextClockEditor();}private void RefreshTextClockEditor(){if(textClockCheck is null||SelectedItem?.ContentKind!=CanvasContentKinds.Clock){if(textClockCheck is not null)textClockCheck.Visibility=Visibility.Collapsed;return;}var c=SelectedItem.Clock;textClockCheck.Visibility=Visibility.Visible;textClockCheck.IsChecked=c.Backgroundless;textClockFont!.Text=c.FontFamily;textClockColor!.Text=c.TextColor;textClockWeight!.SelectedItem=c.FontWeight;}private void ClockChanged(object? s,RoutedEventArgs e){SaveTextClock();}private void ClockChanged(object? s,EventArgs e){SaveTextClock();}private void SaveTextClock(){if(SelectedItem is not {ContentKind:CanvasContentKinds.Clock} item||textClockCheck is null)return;item.Clock.Backgroundless=textClockCheck.IsChecked==true;item.Clock.FontFamily=textClockFont?.Text??"";item.Clock.TextColor=textClockColor?.Text??"";item.Clock.FontWeight=textClockWeight?.SelectedItem is ClockFontWeight w?w:ClockFontWeight.Regular;controller.GetType().GetMethod("SetTheme",BindingFlags.Instance|BindingFlags.NonPublic)?.Invoke(controller,[item,item.Theme]);}
private void MoveLayer(int step){if(SelectedItem is not { } item)return;var type=controller.GetType();var items=controller.Items.OrderBy(x=>x.ZIndex).ToList();var index=items.IndexOf(item);if(step==2){type.GetMethod("BringToFront",BindingFlags.Instance|BindingFlags.NonPublic)?.Invoke(controller,[item]);return;}if(step==-2){type.GetMethod("SendToBack",BindingFlags.Instance|BindingFlags.NonPublic)?.Invoke(controller,[item]);return;}var target=Math.Clamp(index+step,0,items.Count-1);if(target==index)return;(items[index].ZIndex,items[target].ZIndex)=(items[target].ZIndex,items[index].ZIndex);type.GetMethod("NormalizeZOrder",BindingFlags.Instance|BindingFlags.NonPublic)?.Invoke(controller,null);}}
partial class BuiltInContentPicker{internal void AddTextClockOptions(){var fields=GetType();var preview=(CanvasItem?)fields.GetField("previewItem",BindingFlags.Instance|BindingFlags.NonPublic)?.GetValue(this);var options=(StackPanel?)fields.GetField("options",BindingFlags.Instance|BindingFlags.NonPublic)?.GetValue(this);if(preview is null||options is null||options.Tag is string)return;options.Tag="v30";var check=new CheckBox{Content="背景なし・文字だけ"};var font=new TextBox{ToolTip="フォント名"};var color=new TextBox{ToolTip="文字色 (#RRGGBB)"};var weight=new ComboBox{ItemsSource=Enum.GetValues<ClockFontWeight>()};var apply=new Action(()=>{preview.Clock.Backgroundless=check.IsChecked==true;preview.Clock.FontFamily=font.Text;preview.Clock.TextColor=color.Text;preview.Clock.FontWeight=weight.SelectedItem is ClockFontWeight v?v:ClockFontWeight.Regular;});check.Checked+=(_,__)=>apply();check.Unchecked+=(_,__)=>apply();font.LostFocus+=(_,__)=>apply();color.LostFocus+=(_,__)=>apply();weight.SelectionChanged+=(_,__)=>apply();options.Children.Add(new TextBlock{Text="文字時計",Margin=new Thickness(0,12,0,2)});options.Children.Add(check);options.Children.Add(font);options.Children.Add(color);options.Children.Add(weight);}}
